-- Inactive only. Requires reviewed retention, semantic dependencies, and fenced worker.
-- A serialization failure aborts this release; inspect/re-preflight before retry.
BEGIN ISOLATION LEVEL SERIALIZABLE;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
SET LOCAL statement_timeout='3s';
SET LOCAL lock_timeout='500ms';
-- Deactivate and drain separately before rollback. Preserves all run logs and read-model data.
DO $rollback$
declare actual jsonb; installed jsonb; job jsonb; job_id bigint; present integer;
begin
if current_user<>'postgres'then raise exception using errcode='42501',message='snapshot_cron_installer_denied';end if;
if current_setting('transaction_isolation')<>'serializable'then raise exception using errcode='55000',message='snapshot_cron_isolation_required';end if;
if not pg_try_advisory_xact_lock(hashtextextended('provider_snapshot_cron_install_v1',0))
 or not pg_try_advisory_xact_lock(hashtextextended('provider_snapshot_shadow_worker_v1',0))
 or not pg_try_advisory_xact_lock(hashtextextended('provider_snapshot_dispatch_v1',0))
 or not pg_try_advisory_xact_lock(hashtextextended('provider_snapshot_claim_v1',0))then
 raise exception using errcode='55000',message='snapshot_cron_busy';end if;
-- BEGIN native cron environment guard (portable tests explicitly replace only this block).
if (select extversion from pg_extension where extname='pg_cron')is distinct from'1.6.4'
 or current_setting('cron.use_background_workers',true)is distinct from'off'then
 raise exception using errcode='55000',message='snapshot_cron_runtime_unsupported';end if;
if not exists(select 1 from pg_extension e join pg_depend d on d.refobjid=e.oid and d.refclassid='pg_extension'::regclass and d.deptype='e'
 join pg_proc p on p.oid=d.objid and d.classid='pg_proc'::regclass
 where e.extname='pg_cron'and p.oid='cron.schedule(text,text,text)'::regprocedure and p.prorettype='bigint'::regtype)
 or not exists(select 1 from pg_extension e join pg_depend d on d.refobjid=e.oid and d.refclassid='pg_extension'::regclass and d.deptype='e'
 join pg_proc p on p.oid=d.objid and d.classid='pg_proc'::regclass
 where e.extname='pg_cron'and p.oid='cron.alter_job(bigint,text,text,text,text,boolean)'::regprocedure and p.prorettype='void'::regtype)
 or not exists(select 1 from pg_extension e join pg_depend d on d.refobjid=e.oid and d.refclassid='pg_extension'::regclass and d.deptype='e'
 join pg_proc p on p.oid=d.objid and d.classid='pg_proc'::regclass
 where e.extname='pg_cron'and p.oid='cron.unschedule(bigint)'::regprocedure and p.prorettype='boolean'::regtype)
 then raise exception using errcode='55000',message='snapshot_cron_api_drift';end if;
-- END native cron environment guard.
-- Managed pg_cron permits scheduling APIs, not direct cron.job write locks.
-- SERIALIZABLE fixes the names precheck snapshot; a concurrent same-owner
-- schedule upsert must abort rather than overwrite an unseen competing name.
lock table private.provider_snapshot_jobs,private.provider_snapshot_artifacts,private.provider_snapshot_cohorts in share row exclusive mode nowait;
if exists(select 1 from private.provider_snapshot_jobs where status='running'and lease_until>clock_timestamp())then
 raise exception using errcode='55000',message='snapshot_cron_active_lease';end if;
